//! Oracle vectors: PHP 8.5.13 expectations generated by the PHP scripts next to the JSON files.
//!
//! Regenerate with the Docker oracle (`research/php-oracle`, image `twig-oracle:3.31.1`):
//!
//! ```text
//! cd crates/twig-value/tests/vectors
//! for t in float_format float_precision numeric_strings casts array_keys array_ops dims; do
//!   MSYS_NO_PATHCONV=1 docker run --rm -v "$(pwd -W 2>/dev/null || pwd):/t" twig-oracle:3.31.1 \
//!       php /t/$t.gen.php > $t.json
//! done
//! ```
//!
//! Byte strings are stored hex-encoded, doubles as big-endian IEEE bit patterns (hex).

use serde_json::Value as Json;
use twig_value::object::{ArrayObject, ObjectRef, StdClass};
use twig_value::{
    Array, ArrayKey, Diagnostic, FetchMode, KeyContext, Level, Number, PhpError, PhpString, Value,
    convert, dim, float, numeric,
};

fn load(name: &str) -> Json {
    let path = format!("{}/tests/vectors/{}", env!("CARGO_MANIFEST_DIR"), name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("cannot read {path}: {e}"));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("cannot parse {path}: {e}"))
}

fn bits(hex: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(hex, 16).expect("hex bits"))
}

fn to_bits(f: f64) -> String {
    format!("{:016x}", f.to_bits())
}

fn unhex(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("hex byte"))
        .collect()
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn s(j: &Json) -> &str {
    j.as_str()
        .unwrap_or_else(|| panic!("expected string, got {j}"))
}

/// Collects mismatches and fails with a readable summary.
struct Mismatches {
    name: &'static str,
    total: usize,
    items: Vec<String>,
}

impl Mismatches {
    fn new(name: &'static str) -> Self {
        Mismatches {
            name,
            total: 0,
            items: Vec::new(),
        }
    }

    fn check<T: PartialEq + std::fmt::Debug>(
        &mut self,
        what: impl FnOnce() -> String,
        got: T,
        want: T,
    ) {
        self.total += 1;
        if got != want {
            self.items
                .push(format!("{}: got {:?}, want {:?}", what(), got, want));
        }
    }

    fn finish(self) {
        if !self.items.is_empty() {
            let shown: Vec<&String> = self.items.iter().take(30).collect();
            panic!(
                "{}: {} of {} checks differ from PHP:\n{}",
                self.name,
                self.items.len(),
                self.total,
                shown
                    .iter()
                    .map(|s| s.as_str())
                    .collect::<Vec<_>>()
                    .join("\n")
            );
        }
        assert!(self.total > 0, "{}: no checks ran", self.name);
        eprintln!("{}: {} checks match PHP", self.name, self.total);
    }
}

/// Diagnostics as `["W"|"N"|"D", hex message]` pairs, the format the generators emit.
fn diag_list(d: &[Diagnostic]) -> Vec<(String, String)> {
    d.iter()
        .map(|d| {
            let level = match d.level {
                Level::Warning => "W",
                Level::Notice => "N",
                Level::Deprecated => "D",
                Level::UserDeprecated => "UD",
            };
            (level.to_string(), hex(d.message.as_bytes()))
        })
        .collect()
}

fn json_diags(j: &Json) -> Vec<(String, String)> {
    j.as_array()
        .unwrap_or_else(|| panic!("diagnostics must be a list: {j}"))
        .iter()
        .map(|p| (s(&p[0]).to_string(), s(&p[1]).to_string()))
        .collect()
}

/// A PHP value from its typed JSON form: `{"t": "null"|"bool"|"int"|"float"|"string"|"array"|"object", ...}`.
fn typed_value(j: &Json) -> Value {
    match s(&j["t"]) {
        "null" => Value::Null,
        "bool" => Value::Bool(j["v"].as_bool().expect("bool")),
        "int" => Value::Int(j["v"].as_i64().expect("int")),
        "float" => Value::Float(bits(s(&j["bits"]))),
        "string" => Value::from(unhex(s(&j["hex"]))),
        "array" => {
            let n = j["n"].as_u64().expect("array size") as i64;
            (0..n).map(Value::Int).collect::<Array>().into()
        }
        "object" => {
            assert_eq!(s(&j["class"]), "stdClass");
            Value::Object(ObjectRef::new(StdClass::new()))
        }
        other => panic!("unknown typed value {other}"),
    }
}

/// A conversion result in the generators' format: `{"ok": <typed>}` or `{"err": [class, hex message]}`.
fn typed_result(r: &Result<Value, PhpError>) -> Json {
    match r {
        Ok(v) => serde_json::json!({ "ok": typed_json(v) }),
        Err(e) => serde_json::json!({ "err": [e.class().name(), hex(e.message().as_bytes())] }),
    }
}

fn typed_json(v: &Value) -> Json {
    match v {
        Value::Null => serde_json::json!({"t": "null"}),
        Value::Bool(b) => serde_json::json!({"t": "bool", "v": b}),
        Value::Int(i) => serde_json::json!({"t": "int", "v": i}),
        Value::Float(f) => serde_json::json!({"t": "float", "bits": to_bits(*f)}),
        Value::String(s) => serde_json::json!({"t": "string", "hex": hex(s.as_bytes())}),
        Value::Array(a) => serde_json::json!({"t": "array", "n": a.len()}),
        Value::Object(o) => serde_json::json!({"t": "object", "class": o.class_name()}),
    }
}

#[test]
fn float_format() {
    let v = load("float_format.json");
    let mut m = Mismatches::new("float_format");
    for row in v["cases"].as_array().expect("cases") {
        let f = bits(s(&row[0]));
        m.check(
            || format!("(string) {}", s(&row[0])),
            float::double_to_string(f),
            s(&row[1]).to_string(),
        );
        m.check(
            || format!("var_export {}", s(&row[0])),
            float::format_var_export(f),
            s(&row[2]).to_string(),
        );
        // var_dump prints %.*H: the var_export text without the appended ".0".
        let dump = float::format_serialize(f);
        let export = s(&row[2]);
        let want_dump = if f.is_finite() && !dump.contains('.') {
            export.trim_end_matches(".0").to_string()
        } else {
            export.to_string()
        };
        m.check(|| format!("var_dump {}", s(&row[0])), dump, want_dump);
    }
    for row in v["json"].as_array().expect("json") {
        let f = bits(s(&row[0]));
        let got = if f.is_finite() {
            Some(float::format_json(f, false))
        } else {
            None
        };
        m.check(
            || format!("json {}", s(&row[0])),
            got,
            row[1].as_str().map(str::to_string),
        );
    }
    m.finish();
}

#[test]
fn float_precision() {
    let v = load("float_precision.json");
    let mut m = Mismatches::new("float_precision");
    for row in v["cases"].as_array().expect("cases") {
        let f = bits(s(&row[0]));
        for p in 1..=17 {
            m.check(
                || format!("precision {p} {}", s(&row[0])),
                float::double_to_string_with_precision(f, p),
                s(&row[p as usize]).to_string(),
            );
        }
    }
    m.finish();
}

#[test]
fn numeric_strings() {
    let v = load("numeric_strings.json");
    let mut m = Mismatches::new("numeric_strings");
    for case in v["cases"].as_array().expect("cases") {
        let input = unhex(s(&case["s"]));
        let label = || format!("{:?}", PhpString::from(&input[..]));

        m.check(
            || format!("is_numeric {}", label()),
            numeric::is_numeric_str_function(&input).is_some(),
            case["is_numeric"].as_bool().expect("bool"),
        );

        // $s + 0: _zendi_try_convert_scalar_to_number
        let mut d: Vec<Diagnostic> = Vec::new();
        let add = convert::try_to_number(&Value::from(&input[..]), &mut d).expect("no sink errors");
        let got = match add {
            None => serde_json::json!({"err": "TypeError"}),
            Some(Number::Int(i)) => serde_json::json!({"t": "int", "v": i}),
            // `$s + 0` adds int 0 as a double: -0.0 + 0.0 is +0.0.
            Some(Number::Float(f)) => serde_json::json!({"t": "float", "bits": to_bits(f + 0.0)}),
        };
        m.check(|| format!("{} + 0", label()), got, case["add"].clone());
        m.check(
            || format!("{} + 0 diagnostics", label()),
            diag_list(&d),
            json_diags(&case["add_diag"]),
        );

        // (int) / (float)
        let mut d: Vec<Diagnostic> = Vec::new();
        m.check(
            || format!("(int) {}", label()),
            convert::to_long(&Value::from(&input[..]), &mut d).unwrap(),
            case["int"].as_i64().expect("int"),
        );
        m.check(
            || format!("(float) {}", label()),
            to_bits(convert::to_double(&Value::from(&input[..]), &mut d).unwrap()),
            s(&case["float"]).to_string(),
        );
        assert!(d.is_empty(), "casts of strings are silent");

        // array key normalisation
        let key = ArrayKey::from_string(PhpString::from(&input[..]));
        let got = match key {
            ArrayKey::Int(i) => serde_json::json!({"int": i}),
            ArrayKey::Str(_) => serde_json::json!("str"),
        };
        m.check(|| format!("key {}", label()), got, case["key"].clone());

        // $s % 1000003: zendi_try_get_long
        let mut d: Vec<Diagnostic> = Vec::new();
        let got = match convert::try_get_long(&Value::from(&input[..]), &mut d)
            .expect("no sink errors")
        {
            None => serde_json::json!({"err": "TypeError"}),
            Some(l) => serde_json::json!({"t": "int", "v": l.wrapping_rem(1000003)}),
        };
        m.check(
            || format!("{} % 1000003", label()),
            got,
            case["mod"].clone(),
        );
        m.check(
            || format!("{} % diagnostics", label()),
            diag_list(&d),
            json_diags(&case["mod_diag"]),
        );
    }
    m.finish();
}

#[test]
fn casts() {
    let v = load("casts.json");
    let mut m = Mismatches::new("casts");
    for case in v["cases"].as_array().expect("cases") {
        let value = typed_value(&case["v"]);
        let label = || case["v"].to_string();
        let mut d: Vec<Diagnostic> = Vec::new();
        let r = convert::to_bool(&value, &mut d).map(Value::Bool);
        m.check(
            || format!("(bool) {}", label()),
            typed_result(&r),
            case["bool"].clone(),
        );
        m.check(
            || format!("(bool) diag {}", label()),
            diag_list(&d),
            json_diags(&case["bool_diag"]),
        );

        let mut d: Vec<Diagnostic> = Vec::new();
        let r = convert::to_long(&value, &mut d).map(Value::Int);
        m.check(
            || format!("(int) {}", label()),
            typed_result(&r),
            case["int"].clone(),
        );
        m.check(
            || format!("(int) diag {}", label()),
            diag_list(&d),
            json_diags(&case["int_diag"]),
        );

        let mut d: Vec<Diagnostic> = Vec::new();
        let r = convert::to_double(&value, &mut d).map(Value::Float);
        m.check(
            || format!("(float) {}", label()),
            typed_result(&r),
            case["float"].clone(),
        );
        m.check(
            || format!("(float) diag {}", label()),
            diag_list(&d),
            json_diags(&case["float_diag"]),
        );

        let mut d: Vec<Diagnostic> = Vec::new();
        let r = convert::to_string(&value, &mut d).map(Value::String);
        m.check(
            || format!("(string) {}", label()),
            typed_result(&r),
            case["string"].clone(),
        );
        m.check(
            || format!("(string) diag {}", label()),
            diag_list(&d),
            json_diags(&case["string_diag"]),
        );

        m.check(
            || format!("gettype {}", label()),
            twig_value::types::gettype(&value).to_string(),
            s(&case["gettype"]).to_string(),
        );
        m.check(
            || format!("get_debug_type {}", label()),
            twig_value::types::get_debug_type(&value).to_string(),
            s(&case["get_debug_type"]).to_string(),
        );

        // array key in write context (`[$v => 1]`)
        let mut d: Vec<Diagnostic> = Vec::new();
        let r = ArrayKey::from_value(&value, KeyContext::Write, &mut d).map(|k| k.to_value());
        m.check(
            || format!("key {}", label()),
            typed_result(&r),
            case["key"].clone(),
        );
        m.check(
            || format!("key diag {}", label()),
            diag_list(&d),
            json_diags(&case["key_diag"]),
        );
    }
    m.finish();
}

#[test]
fn array_keys() {
    let v = load("array_keys.json");
    let mut m = Mismatches::new("array_keys");
    for case in v["contexts"].as_array().expect("contexts") {
        let value = typed_value(&case["v"]);
        let ctx = match s(&case["ctx"]) {
            "read" => KeyContext::Read,
            "write" => KeyContext::Write,
            "isset" => KeyContext::Isset,
            "unset" => KeyContext::Unset,
            "array_key_exists" => KeyContext::ArrayKeyExists,
            other => panic!("unknown context {other}"),
        };
        let mut d: Vec<Diagnostic> = Vec::new();
        let r = ArrayKey::from_value(&value, ctx, &mut d).map(|k| k.to_value());
        m.check(
            || format!("{} key {}", s(&case["ctx"]), case["v"]),
            typed_result(&r),
            case["key"].clone(),
        );
        m.check(
            || format!("{} diag {}", s(&case["ctx"]), case["v"]),
            diag_list(&d),
            json_diags(&case["diag"]),
        );
    }
    m.finish();
}

#[test]
fn array_ops() {
    let v = load("array_ops.json");
    let mut m = Mismatches::new("array_ops");
    for (n, case) in v["cases"].as_array().expect("cases").iter().enumerate() {
        let mut a = Array::new();
        let mut keep: Vec<Array> = Vec::new();
        let mut log: Vec<Json> = Vec::new();
        for op in case["ops"].as_array().expect("ops") {
            match s(&op[0]) {
                "set" => {
                    a.insert(op[1].as_i64().expect("int key"), Value::Int(1));
                }
                "sets" => {
                    a.insert(ArrayKey::from(s(&op[1])), Value::Int(1));
                }
                "push" => match a.push(Value::Int(2)) {
                    Ok(k) => log.push(serde_json::json!(k)),
                    Err(e) => log.push(serde_json::json!(e.message().to_string())),
                },
                "unset" => {
                    a.remove(&ArrayKey::Int(op[1].as_i64().expect("int key")));
                }
                "unsets" => {
                    a.remove(&ArrayKey::from(s(&op[1])));
                }
                "copy" => keep.push(a.clone()),
                other => panic!("unknown op {other}"),
            }
        }
        let keys: Vec<Json> = a
            .keys()
            .map(|k| match k {
                ArrayKey::Int(i) => serde_json::json!(i),
                ArrayKey::Str(s) => serde_json::json!(s.to_string()),
            })
            .collect();
        m.check(
            || format!("case {n} pushes {:?}", case["ops"]),
            Json::Array(log),
            case["pushes"].clone(),
        );
        m.check(
            || format!("case {n} keys {:?}", case["ops"]),
            Json::Array(keys),
            case["keys"].clone(),
        );
        let next = match a.clone().push(Value::Null) {
            Ok(k) => serde_json::json!(k),
            Err(e) => serde_json::json!(e.message().to_string()),
        };
        m.check(
            || format!("case {n} next {:?}", case["ops"]),
            next,
            case["next"].clone(),
        );
        drop(keep);
    }
    m.finish();
}

/// The containers of `dims.gen.php`, in the same order.
fn dim_containers() -> Vec<Value> {
    let mut a = Array::new();
    a.insert("k", "v");
    a.insert(5, "five");
    a.insert("", "empty");
    a.insert(-1, "neg");
    a.insert(0, "zero");
    a.insert(1, Value::Null);
    a.insert("n", Value::Null);
    a.insert(i64::MAX, "max");
    a.insert("x", 0);
    a.insert("y", "0");
    a.insert("z", f64::NAN);
    a.insert(2, "two");
    vec![
        Value::Array(a),
        Value::Array(Array::new()),
        Value::from("abc"),
        Value::from(""),
        Value::from("a0"),
        Value::from(&b"0\0x"[..]),
        Value::Null,
        Value::Bool(true),
        Value::Bool(false),
        Value::Int(0),
        Value::Int(7),
        Value::Float(1.5),
        Value::Object(ObjectRef::new(StdClass::new())),
    ]
}

/// The `count()` inputs of `dims.gen.php`, in the same order.
fn count_inputs() -> Vec<Value> {
    let mut nested = Array::new();
    nested.push(1).unwrap();
    nested
        .push(Value::Array(Array::from_values([
            Value::Int(2),
            Value::Int(3),
        ])))
        .unwrap();
    nested
        .push(Value::Array(Array::from_values([Value::Array(
            Array::from_values([Value::Int(4)]),
        )])))
        .unwrap();
    nested.insert(
        "x",
        Value::Array(Array::from_values([
            Value::Int(5),
            Value::Object(ObjectRef::new(StdClass::new())),
        ])),
    );
    vec![
        Value::Array(Array::new()),
        Value::Array(Array::from_values([Value::Int(1), Value::Int(2)])),
        Value::Array(nested),
        Value::from("abc"),
        Value::Null,
        Value::Int(1),
        Value::Float(1.5),
        Value::Bool(true),
        Value::Object(ObjectRef::new(StdClass::new())),
        Value::Object(
            ArrayObject::new(Array::from_values([
                Value::Int(1),
                Value::Int(2),
                Value::Int(3),
            ]))
            .into_ref(),
        ),
    ]
}

#[test]
fn dims() {
    let v = load("dims.json");
    let mut m = Mismatches::new("dims");
    let containers = dim_containers();
    for case in v["cases"].as_array().expect("cases") {
        let container = &containers[case["c"].as_u64().expect("container index") as usize];
        let offset = typed_value(&case["o"]);
        let label = || format!("container #{} offset {}", case["c"], case["o"]);

        let mut d: Vec<Diagnostic> = Vec::new();
        let r = dim::read(container, &offset, FetchMode::Read, &mut d);
        m.check(
            || format!("read {}", label()),
            typed_result(&r),
            case["read"].clone(),
        );
        m.check(
            || format!("read diag {}", label()),
            diag_list(&d),
            json_diags(&case["read_diag"]),
        );

        let mut d: Vec<Diagnostic> = Vec::new();
        // `$c[$o] ?? 'DFLT'`: a null result selects the default.
        let r = dim::read(container, &offset, FetchMode::Isset, &mut d)
            .map(|v| if v.is_null() { Value::from("DFLT") } else { v });
        m.check(
            || format!("quiet {}", label()),
            typed_result(&r),
            case["quiet"].clone(),
        );
        m.check(
            || format!("quiet diag {}", label()),
            diag_list(&d),
            json_diags(&case["quiet_diag"]),
        );

        let mut d: Vec<Diagnostic> = Vec::new();
        let r = dim::isset(container, &offset, &mut d).map(Value::Bool);
        m.check(
            || format!("isset {}", label()),
            typed_result(&r),
            case["isset"].clone(),
        );
        m.check(
            || format!("isset diag {}", label()),
            diag_list(&d),
            json_diags(&case["isset_diag"]),
        );

        let mut d: Vec<Diagnostic> = Vec::new();
        let r = dim::empty(container, &offset, &mut d).map(Value::Bool);
        m.check(
            || format!("empty {}", label()),
            typed_result(&r),
            case["empty"].clone(),
        );
        m.check(
            || format!("empty diag {}", label()),
            diag_list(&d),
            json_diags(&case["empty_diag"]),
        );
    }
    let inputs = count_inputs();
    let rows = v["counts"].as_array().expect("counts");
    assert_eq!(rows.len(), inputs.len() * 4, "count rows");
    for (i, row) in rows.iter().enumerate() {
        let value = &inputs[i / 4];
        let mode = row["mode"].as_i64().expect("mode");
        let mut d: Vec<Diagnostic> = Vec::new();
        let r = dim::count(value, mode, &mut d).map(Value::Int);
        m.check(
            || format!("count {} mode {mode}", row["v"]),
            typed_result(&r),
            row["r"].clone(),
        );
        m.check(
            || format!("count diag {} mode {mode}", row["v"]),
            diag_list(&d),
            json_diags(&row["diag"]),
        );
    }
    m.finish();
}

/// `class S { function __toString(): string { return '12'; } }` of `params.gen.php`.
struct Stringy {
    class: twig_value::object::ClassRef,
}

impl twig_value::object::Object for Stringy {
    fn class(&self) -> &twig_value::object::ClassRef {
        &self.class
    }

    fn call(
        &self,
        _this: &ObjectRef,
        method: &str,
        _args: twig_value::object::CallArgs,
        _diag: &mut dyn twig_value::Diagnostics,
    ) -> twig_value::PhpResult<Value> {
        match method {
            "__tostring" => Ok(Value::from("12")),
            _ => Err(twig_value::object::undefined_method(&self.class, method)),
        }
    }
}

/// A value of `params.gen.php` from its typed form (objects by class name).
fn param_value(j: &Json) -> Value {
    if s(&j["t"]) == "object" {
        return match s(&j["class"]) {
            "stdClass" => Value::Object(ObjectRef::new(StdClass::new())),
            "S" => Value::Object(ObjectRef::new(Stringy {
                class: twig_value::object::ClassBuilder::class("S")
                    .method("__toString")
                    .build(),
            })),
            "ArrayObject" => {
                Value::Object(ArrayObject::new(Array::from_values([Value::Int(1)])).into_ref())
            }
            other => panic!("unknown class {other}"),
        };
    }
    typed_value(j)
}

#[test]
fn params() {
    use twig_value::param::{self, Arg, DeclaredType, TypeMask as T, UserArg};
    let user: &[(&str, DeclaredType<'static>)] = &[
        ("u_int", DeclaredType::builtin(T::INT)),
        ("u_float", DeclaredType::builtin(T::FLOAT)),
        ("u_string", DeclaredType::builtin(T::STRING)),
        ("u_bool", DeclaredType::builtin(T::BOOL)),
        ("u_nint", DeclaredType::builtin(T::INT | T::NULL)),
        ("u_nstring", DeclaredType::builtin(T::STRING | T::NULL)),
        ("u_int_float", DeclaredType::builtin(T::INT | T::FLOAT)),
        ("u_string_int", DeclaredType::builtin(T::STRING | T::INT)),
        ("u_int_bool", DeclaredType::builtin(T::INT | T::BOOL)),
        (
            "u_float_string",
            DeclaredType::builtin(T::FLOAT | T::STRING),
        ),
        (
            "u_bool_string_null",
            DeclaredType::builtin(T::BOOL | T::STRING | T::NULL),
        ),
        ("u_false_int", DeclaredType::builtin(T::FALSE | T::INT)),
        ("u_array", DeclaredType::builtin(T::ARRAY)),
        ("u_iterable", DeclaredType::iterable()),
        ("u_countable", DeclaredType::new(&["Countable"], T::ARRAY)),
        ("u_object", DeclaredType::builtin(T::OBJECT)),
        ("u_nstringable", DeclaredType::new(&["Stringable"], T::NULL)),
        ("u_mixed", DeclaredType::builtin(T::MIXED)),
    ];
    let v = load("params.json");
    let mut m = Mismatches::new("params");
    for case in v["cases"].as_array().expect("cases") {
        let value = param_value(&case["typed"]);
        let label = case["typed"].to_string();
        let mut check = |what: &str, r: Result<Value, PhpError>, d: &[Diagnostic], want: &Json| {
            m.check(
                || format!("{what} {label}"),
                typed_result(&r),
                want[0].clone(),
            );
            m.check(
                || format!("{what} diag {label}"),
                diag_list(d),
                json_diags(&want[1]),
            );
        };

        let mut d: Vec<Diagnostic> = Vec::new();
        let r = param::parse_long(&value, &Arg::new("intdiv", 1, "num1"), &mut d).map(Value::Int);
        check("intdiv", r, &d, &case["int"]);

        let mut d: Vec<Diagnostic> = Vec::new();
        let r = param::parse_double(&value, &Arg::new("fdiv", 1, "num1"), &mut d)
            .map(|f| Value::Float(f / 1.0));
        check("fdiv", r, &d, &case["float"]);

        let mut d: Vec<Diagnostic> = Vec::new();
        let r =
            param::parse_str(&value, &Arg::new("str_pad", 1, "string"), &mut d).map(Value::String);
        check("str_pad", r, &d, &case["string"]);

        let mut d: Vec<Diagnostic> = Vec::new();
        let r = param::parse_bool(&value, &Arg::new("array_slice", 4, "preserve_keys"), &mut d)
            .map(|b| Value::Int(if b { 5 } else { 0 }));
        check("array_slice preserve_keys", r, &d, &case["bool"]);

        let mut d: Vec<Diagnostic> = Vec::new();
        // abs(): PHP_INT_MIN overflows to float.
        let r = param::parse_number(&value, &Arg::new("abs", 1, "num"), &mut d).map(|n| match n {
            Number::Int(i64::MIN) => Value::Float(-(i64::MIN as f64)),
            Number::Int(i) => Value::Int(i.abs()),
            Number::Float(f) => Value::Float(f.abs()),
        });
        check("abs", r, &d, &case["number"]);

        for (name, ty) in user {
            let mut d: Vec<Diagnostic> = Vec::new();
            let r = param::verify_user_arg(value.clone(), ty, &UserArg::new(name, 1, "x"), &mut d);
            check(name, r, &d, &case[*name]);
        }
    }
    m.finish();
}

#[test]
fn strtod() {
    let v = load("strtod.json");
    let mut m = Mismatches::new("strtod");
    for row in v["cases"].as_array().expect("cases") {
        let input = s(&row[0]);
        let shown = || {
            if input.len() > 80 {
                format!("{}… ({} bytes)", &input[..80], input.len())
            } else {
                input.to_string()
            }
        };
        m.check(
            || format!("(float) {}", shown()),
            to_bits(numeric::strtod(input.as_bytes()).0),
            s(&row[1]).to_string(),
        );
    }
    m.finish();
}
